@Override
	public void onEntityCollision(IMultiblockContext<State> ctx, BlockPos posInMultiblock, Entity collided)
	{
		final Level level = collided.level();
		if(!new BlockPos(0, 1, 1).equals(posInMultiblock)||level.isClientSide)
			return;
		else if(!(collided instanceof ItemEntity)||!collided.isAlive())
			return;
		final State state = ctx.getState();
		final BlockPos absoluteCollisionPos = ctx.getLevel().toAbsolute(posInMultiblock);
		List<Pair<ItemEntity, ItemStack>> itemsOnConveyor = level.getEntitiesOfClass(
				ItemEntity.class, AABB.unitCubeFromLowerCorner(Vec3.atLowerCornerOf(absoluteCollisionPos))
		).stream().map(itemEntity1 -> Pair.of(itemEntity1, itemEntity1.getItem())).toList();
		if(itemsOnConveyor.isEmpty())
			return;

		ItemStack[] stacks = itemsOnConveyor.stream().map(Pair::getSecond).toArray(ItemStack[]::new);
		RecipeHolder<BottlingMachineRecipe> recipe = BottlingMachineRecipe.findRecipe(level, state.tank.getFluid(), stacks);
		if(recipe==null&&!Utils.isFluidRelatedItemStack(stacks[0]))
			return;

		MultiblockProcessInWorld<BottlingMachineRecipe> process;
		NonNullList<ItemStack> displayStacks;
		if(recipe==null)
		{
			ItemStack inputItem = stacks[0].copyWithCount(1);
			displayStacks = Utils.createNonNullItemStackListFromItemStack(inputItem);
			process = new BottlingProcess(inputItem, inputItem.copy(), state);
		}
		else
		{
			displayStacks = recipe.value().getDisplayStacks(stacks);
			process = new BottlingProcess(recipe, displayStacks, state);
		}

		if(state.processor.addProcessToQueue(process, level, false))
			for(ItemStack stack : displayStacks)
				itemsOnConveyor.stream()
						.filter(t -> ItemStack.isSameItemSameComponents(t.getSecond(), stack))
						.findFirst()
						.ifPresent(t -> {
							ItemStack remaining = t.getSecond().copy();
							remaining.shrink(stack.getCount());
							t.getFirst().setItem(remaining);
							if(remaining.isEmpty())
								t.getFirst().discard();
						});
	}

@Override
	public void tickServer(IMultiblockContext<State> context)
	{
		final State state = context.getState();
		boolean active = state.processor.tickServer(state, context.getLevel(), state.rsState.isEnabled(context));
		state.active = active;
		if(active)
			// TODO syncing every tick while the machine is active is a hack. This was how it worked in the old system,
			//  but should be avoided
			context.requestMasterBESync();
	}

@Override
	public void tickClient(IMultiblockContext<State> context)
	{
		final State state = context.getState();
		if(!state.active)
			return;
		final IMultiblockLevel level = context.getLevel();
		final Level rawLevel = level.getRawLevel();
		for(final MultiblockProcess<BottlingMachineRecipe, ProcessContextInWorld<BottlingMachineRecipe>> process : state.processor.getQueue())
		{
			Player localPlayer = ImmersiveEngineering.proxy.getClientPlayer();
			if(process.processTick==STANDARD_TRANSPORT_TIME-12)
			{
				final BlockPos soundPos = level.toAbsolute(new BlockPos(1, 1, 1));
				rawLevel.playSound(localPlayer, soundPos, IESounds.bottling.value(), SoundSource.BLOCKS, .125F, 0.8F);
				break;
			}
		}
	}

@Override
	public void doProcessTick(ProcessContextInWorld<BottlingMachineRecipe> context, IMultiblockLevel level)
	{
		super.doProcessTick(context, level);

		final Level rawLevel = level.getRawLevel();
		float transPoint = getMaxTicks(rawLevel)*transformationPoint;
		if(processTick >= transPoint&&processTick < 1+transPoint)
		{
			FluidStack fs = tank.getFluid();
			if(!fs.isEmpty())
			{
				// filling recipes use custom logic
				if(isFilling)
				{
					ItemStack ret = FluidUtils.fillFluidContainer(tank, filledContainer.get(0), ItemStack.EMPTY, null);
					if(!ret.isEmpty())
						filledContainer.set(0, ret);
					// reduce process tick, if the item should be held in place
					if(!allowPartialFill.getAsBoolean()&&!FluidUtils.isFluidContainerFull(ret))
						processTick--;
				}
				// normal recipes just consume the fluid at this point
				else
					tank.drain(getRecipe(rawLevel).fluidInput.amount(), FluidAction.EXECUTE);
			}
		}
	}

public boolean tickServer(CTX ctx, IMultiblockLevel level, boolean canWork)
	{
		ctx.getEnergy().updateAverage();
		if(!canWork)
			return false;

		int i = 0;
		Iterator<MultiblockProcess<R, CTX>> processIterator = processQueue.iterator();
		boolean tickedAny = false;
		while(processIterator.hasNext()&&i++ < maxProcessPerTick)
		{
			MultiblockProcess<R, CTX> process = processIterator.next();
			if(process.canProcess(ctx, level.getRawLevel()))
			{
				process.doProcessTick(ctx, level);
				tickedAny = true;
			}
			if(process.clearProcess)
			{
				processIterator.remove();
				onQueueChange.run();
			}
		}
		if(tickedAny)
			markDirty.run();
		return tickedAny;
	}

public boolean canProcess(CTX context, Level level)
	{
		LevelDependentData<R> levelData = getLevelData(level);
		if(levelData.recipe==null)
			return true;
		if(context.getEnergy().extractEnergy(levelData.energyPerTick, true)==levelData.energyPerTick)
		{
			List<ItemStack> outputs = getRecipeItemOutputs(level, context);
			if(outputs!=null)
				for(ItemStack output : outputs)
					if(!output.isEmpty()&&!canOutputItem(context, output))
						return false;
			List<FluidStack> fluidOutputs = levelData.recipe.getFluidOutputs();
			if(fluidOutputs!=null)
				for(FluidStack output : fluidOutputs)
					if(!canOutputFluid(context, output))
						return false;
			return context.additionalCanProcessCheck(this, level);
		}
		return false;
	}

public void doProcessTick(CTX context, IMultiblockLevel level)
	{
		final Level rawLevel = level.getRawLevel();
		LevelDependentData<R> levelData = getLevelData(rawLevel);
		if(levelData.recipe==null)
		{
			this.clearProcess = true;
			return;
		}
		// perform initial tick
		context.getEnergy().extractEnergy(levelData.energyPerTick, false);
		this.processTick += 1;

		// initialize if not yet happened
		if(extraProcessTicks < 0)
			extraProcessTicks = levelData.recipe.getMultipleProcessTicks();

		if(extraProcessTicks >= 0)
		{
			int averageInsertion = context.getEnergy().getAverageInsertion();
			int averageExtraction = context.getEnergy().getAverageExtraction();
			if(averageInsertion < averageExtraction)
				extraProcessTicks = Math.max(0, extraProcessTicks-1);
			else if(averageInsertion > averageExtraction)
				extraProcessTicks = Math.min(levelData.recipe.getMultipleProcessTicks(), extraProcessTicks+1);

			int possibleTicks = Math.min(
					Math.min(
							extraProcessTicks, // extra ticks that can step up and down
							levelData.maxTicks-this.processTick // ticks remaining in the recipe
					),
					Math.min(
							averageInsertion/levelData.energyPerTick, // max ticks possible with current insertion
							context.getEnergy().getEnergyStored()/levelData.energyPerTick // max ticks possible with current stored power
					)
			);
			if(possibleTicks > 0)
			{
				context.getEnergy().extractEnergy(levelData.energyPerTick*possibleTicks, false);
				this.processTick += possibleTicks;
			}
		}

		if(this.processTick >= levelData.maxTicks)
			this.processFinish(context, level);
	}

protected void processFinish(CTX context, IMultiblockLevel level)
	{
		final Level rawLevel = level.getRawLevel();
		List<ItemStack> outputs = getRecipeItemOutputs(rawLevel, context);
		if(outputs!=null)
			for(ItemStack output : outputs)
				outputItem(context, output, level);
		List<FluidStack> fluidOutputs = getRecipeFluidOutputs(rawLevel);
		if(fluidOutputs!=null)
			for(FluidStack output : fluidOutputs)
				outputFluid(context, output);

		context.onProcessFinish(this, level.getRawLevel());
		this.clearProcess = true;
	}

@Override
	protected void processFinish(ProcessContextInWorld<R> context, IMultiblockLevel level)
	{
		super.processFinish(context, level);
		int size = -1;

		R recipe = getLevelData(level.getRawLevel()).recipe();
		if(recipe==null)
			return;
		for(ItemStack inputItem : this.inputItems)
		{
			for(IngredientWithSize s : recipe.getItemInputs())
				if(s.test(inputItem))
				{
					size = s.getCount();
					break;
				}

			if(size > 0&&inputItem.getCount() > size)
			{
				inputItem.split(size);
				processTick = 0;
				clearProcess = false;
			}
		}
	}

@Override
	protected void outputItem(ProcessContextInWorld<R> context, ItemStack output, IMultiblockLevel level)
	{
		context.doProcessOutput(output, level);
	}

public static void onLivingUpdate(EntityTickEvent.Post event) {
		Entity entity = event.getEntity();
		if (entity.level().isClientSide() || entity instanceof Player || !(entity instanceof LivingEntity livingEntity)) {
			return;
		}
		if (livingEntity instanceof Monster monster && hasPendingBackpackAddition(monster)) {
			setPendingBackpackAddition(monster, false);
			if (monster.getItemBySlot(EquipmentSlot.CHEST).isEmpty()) {
				addBackpack(monster, entity.level(), entity.level().getRandom());
			}
		}
		if (!hasSpawnedJukeboxUpgrade(livingEntity)) {
			return;
		}
		ItemStack backpack = livingEntity.getItemBySlot(EquipmentSlot.CHEST);
		if (!(backpack.getItem() instanceof BackpackItem)) {
			clearSpawnedBackpackData(livingEntity);
			return;
		}

		IBackpackWrapper backpackWrapper = BackpackWrapper.fromStack(backpack);
		backpackWrapper.getUpgradeHandler().getTypeWrappers(JukeboxUpgradeItem.TYPE).forEach(wrapper -> {
			if (wrapper.isPlaying()) {
				wrapper.tick(livingEntity, entity.level(), entity.blockPosition());
			} else {
				wrapper.play(livingEntity);
			}
		});
	}

static void handleBackpackAdditionOnSpawn(Monster monster, LevelAccessor level, MobSpawnType spawnType) {
		RandomSource rnd = level.getRandom();
		if (!shouldAddBackpack(monster, rnd)) {
			return;
		}

		if (shouldDeferBackpackAddition(level, spawnType)) {
			setPendingBackpackAddition(monster, true);
			return;
		}

		addBackpack(monster, level, rnd);
	}

private static boolean shouldDeferBackpackAddition(LevelAccessor level, MobSpawnType spawnType) {
		MinecraftServer server = level.getServer();
		return spawnType == MobSpawnType.TRIAL_SPAWNER || server == null || !server.isSameThread();
	}

private static void addBackpack(Monster monster, LevelAccessor level, RandomSource rnd) {
		int difficultyIndex = 0;
		if (Config.SERVER.entityBackpackAdditions.localDifficultyEffectsBackpackSpawns.getAsBoolean()) {
			float localDifficulty = level.getCurrentDifficultyAt(monster.blockPosition()).getEffectiveDifficulty();
			difficultyIndex = Ints.constrainToRange((int) Math.floor(DIFFICULTY_BACKPACK_CHANCES.size() / MAX_LOCAL_DIFFICULTY * localDifficulty - 0.1f), 0,
					DIFFICULTY_BACKPACK_CHANCES.size() - 1);
		}

		RandHelper.getRandomWeightedElement(rnd, DIFFICULTY_BACKPACK_CHANCES.get(difficultyIndex)).ifPresent(backpackAddition -> {
			ItemStack backpack = new ItemStack(backpackAddition.getBackpackItem());
			int minDifficulty = backpackAddition.getMinDifficulty();
			equipBackpack(monster, backpack, minDifficulty, Config.SERVER.entityBackpackAdditions.playJukebox.get() && rnd.nextInt(4) == 0, level, rnd);
			applyPotions(monster, Math.max(minDifficulty, rnd.nextInt(MAX_DIFFICULTY + 1)), minDifficulty, rnd);
			raiseHealth(monster, minDifficulty);
			if (Config.SERVER.entityBackpackAdditions.equipWithArmor.get()) {
				equipArmorPiece(monster, rnd, minDifficulty, backpackAddition.getHelmetChances(), EquipmentSlot.HEAD, level);
				equipArmorPiece(monster, rnd, minDifficulty, backpackAddition.getLeggingsChances(), EquipmentSlot.LEGS, level);
				equipArmorPiece(monster, rnd, minDifficulty, backpackAddition.getBootsChances(), EquipmentSlot.FEET, level);
			}
			setSpawnedBackpack(monster, true);
		});
	}

private static void equipBackpack(Monster monster, ItemStack backpack, int minDifficulty, boolean playMusicDisc, LevelAccessor level, RandomSource rnd) {
		setSpawnedBackpack(monster, true);
		getSpawnEgg(monster.getType()).ifPresent(egg -> {
			IBackpackWrapper wrapper = BackpackWrapper.fromStack(backpack);
			wrapper.setColors(egg.getColor(0) | 0xFF_000000, egg.getColor(1) | 0xFF_000000);
			int partialRolls = rnd.nextInt(minDifficulty, minDifficulty + 3);
			if (partialRolls != 0) {
				setLoot(monster, wrapper, level, (float) partialRolls / MAX_DIFFICULTY);
			}
			if (playMusicDisc) {
				wrapper.getInventoryHandler(); // just to assign uuid and real upgrade handler
				if (wrapper.getUpgradeHandler().getSlots() > 0) {
					setSpawnedJukeboxUpgrade(monster, true);
					addJukeboxUpgradeAndRandomDisc(level.getRandom(), wrapper, rnd);
				}
			}
		});
		monster.setItemSlot(EquipmentSlot.CHEST, backpack);
		monster.setDropChance(EquipmentSlot.CHEST, 0);
	}

private static boolean hasPendingBackpackAddition(LivingEntity entity) {
		return getBackpackEntityData(entity).getBoolean(ENTITY_DATA_PENDING_BACKPACK_ADDITION);
	}

private static void setPendingBackpackAddition(LivingEntity entity, boolean pendingBackpackAddition) {
		if (pendingBackpackAddition) {
			getOrCreateBackpackEntityData(entity).putBoolean(ENTITY_DATA_PENDING_BACKPACK_ADDITION, true);
		} else {
			CompoundTag backpackEntityData = getBackpackEntityData(entity);
			backpackEntityData.remove(ENTITY_DATA_PENDING_BACKPACK_ADDITION);
			if (backpackEntityData.isEmpty()) {
				entity.getPersistentData().remove(ENTITY_DATA_TAG);
			}
		}
	}

public boolean hurt(DamageSource pSource, float pAmount) {
        if (this.getHealth() <= 10.0F){
            if (pSource.is(DamageTypes.CACTUS) || pSource.is(DamageTypes.SWEET_BERRY_BUSH) || pSource.is(DamageTypeTags.WITCH_RESISTANT_TO)){
                return false;
            }
        }

        if (pSource.getEntity() instanceof LivingEntity livingentity && livingentity != this){
            this.toHealTime = MathHelper.secondsToTicks(15);
            if (MobsConfig.CroneThornDefense.get()) {
                if (!pSource.is(DamageTypeTags.AVOIDS_GUARDIAN_THORNS) && !pSource.is(DamageTypes.THORNS)) {
                    float thorn = 2.0F;
                    if (this.level.getDifficulty() == Difficulty.HARD) {
                        thorn *= 2.0F;
                    }
                    livingentity.hurt(this.damageSources().thorns(this), thorn);
                }
            }
            if (pAmount >= 6 && this.overwhelmed <= 0) {
                this.hitTimes += 1;
                this.lastHitTime = 25;
            }
            if (pAmount >= 15 || this.hitTimes > 3){
                this.overwhelmed = MathHelper.secondsToTicks(15);
            }
        }

        return super.hurt(pSource, pAmount);
    }

public void aiStep() {
        if (!this.level.isClientSide && this.isAlive()) {
            if (this.lastHitTime > 0){
                --this.lastHitTime;
            } else if (this.hitTimes > 0) {
                this.hitTimes = 0;
            }
            if (this.toHealTime > 0) {
                --this.toHealTime;
            }
            if (this.overwhelmed > 0) {
                --this.overwhelmed;
            }
            this.healRaidersGoal.decrementCooldown();
            this.attackPlayersGoal.setCanAttack(this.healRaidersGoal.getCooldown() <= 0);

            if (this.isDrinkingPotion()) {
                if (this.usingTime-- <= 0) {
                    this.setUsingItem(false);
                    ItemStack itemstack = this.getMainHandItem();
                    this.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
                    if (itemstack.is(ModItems.BREW.get())) {
                        List<MobEffectInstance> list = PotionUtils.getMobEffects(itemstack);
                        for (MobEffectInstance mobeffectinstance : list) {
                            this.addEffect(new MobEffectInstance(mobeffectinstance));
                        }
                        List<BrewEffectInstance> list1 = BrewUtils.getBrewEffects(itemstack);
                        for (BrewEffectInstance brewEffectInstance : list1) {
                            brewEffectInstance.getEffect().drinkBlockEffect(this, this, this, brewEffectInstance.getAmplifier(), BrewUtils.getAreaOfEffect(itemstack));
                        }
                    }

                    this.getAttribute(Attributes.MOVEMENT_SPEED).removeModifier(SPEED_MODIFIER_DRINKING);
                }
            } else {
                int amp = 0;
                if (this.level.getRandom().nextFloat() <= 0.05F && this.level.getDifficulty() == Difficulty.NORMAL){
                    amp = 2;
                } else if (this.level.getRandom().nextFloat() <= 0.25F){
                    amp = 1;
                }
                List<MobEffectInstance> mobEffectInstance = new ArrayList<>();
                List<BrewEffectInstance> brewEffectInstance = new ArrayList<>();
                if (this.random.nextFloat() < 0.15F && (this.isInWall() || (this.getLastDamageSource() != null && this.getLastDamageSource().is(DamageTypes.IN_WALL)))){
                    brewEffectInstance.add(new BrewEffectInstance(new BlindJumpBrewEffect(0), 1, amp));
                } else if (this.random.nextFloat() < 0.15F && this.getLastDamageSource() != null && (this.getLastDamageSource().is(DamageTypes.CACTUS) || this.getLastDamageSource().is(DamageTypes.SWEET_BERRY_BUSH))){
                    brewEffectInstance.add(new BrewEffectInstance(new HarvestBlockEffect()));
                } else if (this.random.nextFloat() < 0.15F && this.getHealth() < this.getMaxHealth() && (this.getTarget() == null || this.toHealTime == 0)) {
                    mobEffectInstance.add(new MobEffectInstance(MobEffects.HEAL, 1, amp));
                } else if (this.random.nextFloat() < 0.15F && this.isEyeInFluidType(ForgeMod.WATER_TYPE.get()) && !this.hasEffect(MobEffects.WATER_BREATHING)) {
                    mobEffectInstance.add(new MobEffectInstance(MobEffects.WATER_BREATHING, 3600));
                    mobEffectInstance.add(new MobEffectInstance(GoetyEffects.SWIFT_SWIM.get(), 3600));
                } else if (this.random.nextFloat() < 0.15F && (this.isOnFire() || this.getLastDamageSource() != null && this.getLastDamageSource().is(DamageTypeTags.IS_FIRE)) && !this.hasEffect(MobEffects.FIRE_RESISTANCE)) {
                    mobEffectInstance.add(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 3600));
                } else if (this.random.nextFloat() < 0.15F && this.getLastDamageSource() != null && this.getLastDamageSource().is(DamageTypeTags.IS_FALL) && !this.hasEffect(MobEffects.SLOW_FALLING)){
                    mobEffectInstance.add(new MobEffectInstance(MobEffects.SLOW_FALLING, 3600));
                } else if (this.random.nextFloat() < 0.15F && this.getLastDamageSource() != null && ModDamageSource.physicalAttacks(this.getLastDamageSource()) && !this.hasEffect(GoetyEffects.REPULSIVE.get())){
                    mobEffectInstance.add(new MobEffectInstance(GoetyEffects.REPULSIVE.get(), 1800 / (amp + 1), amp));
                } else if (this.random.nextFloat() < 0.15F && this.getTarget() != null) {
                    if ((this.random.nextFloat() <= 0.15F && this.getTarget().distanceTo(this) <= 4.0F)){
                        brewEffectInstance.add(new BrewEffectInstance(new BlindJumpBrewEffect(0), 1, amp));
                    } else if (this.random.nextFloat() <= 0.15F && !this.hasEffect(MobEffects.REGENERATION)){
                        mobEffectInstance.add(new MobEffectInstance(MobEffects.REGENERATION, 900 / (amp + 1), amp));
                        if (this.random.nextFloat() < 0.25F && MobUtil.isInSunlight(this) && !this.hasEffect(GoetyEffects.PHOTOSYNTHESIS.get())){
                            mobEffectInstance.add(new MobEffectInstance(GoetyEffects.PHOTOSYNTHESIS.get(), 1800));
                        }
                    } else if (this.random.nextFloat() < 0.05F && !this.hasEffect(MobEffects.DAMAGE_RESISTANCE)){
                        mobEffectInstance.add(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 1800));
                    } else if (this.random.nextFloat() < 0.05F && !this.hasEffect(GoetyEffects.FROSTY_AURA.get()) && !this.hasEffect(GoetyEffects.FIERY_AURA.get())) {
                        if (this.random.nextBoolean()) {
                            if (!this.getTarget().hasEffect(GoetyEffects.FREEZING.get()) && !this.getTarget().hasEffect(MobEffects.FIRE_RESISTANCE) && !this.getTarget().fireImmune()) {
                                mobEffectInstance.add(new MobEffectInstance(GoetyEffects.FIERY_AURA.get(), 1800 / (amp + 1), amp));
                            }
                        } else {
                            if (!this.getTarget().isOnFire() && this.getTarget().canFreeze()){
                                mobEffectInstance.add(new MobEffectInstance(GoetyEffects.FROSTY_AURA.get(), 1800 / (amp + 1), amp));
                            }
                        }
                    }
                } else if (this.random.nextFloat() <= 0.15F && MobUtil.isInWeb(this) && !this.hasEffect(GoetyEffects.CLIMBING.get())){
                    mobEffectInstance.add(new MobEffectInstance(GoetyEffects.CLIMBING.get(), 3600));
                } else if (this.random.nextFloat() < 0.05F && MobUtil.hasLongNegativeEffects(this)) {
                    brewEffectInstance.add(new BrewEffectInstance(new PurifyBrewEffect("purify_debuff", 0, 0, MobEffectCategory.BENEFICIAL, 0x385858, true)));
                }

                if (!mobEffectInstance.isEmpty() || !brewEffectInstance.isEmpty()) {
                    ItemStack brew = BrewUtils.setCustomEffects(new ItemStack(ModItems.BREW.get()), mobEffectInstance, brewEffectInstance);
                    BrewUtils.setAreaOfEffect(brew, this.level.getRandom().nextInt(amp + 1));
                    brew.getOrCreateTag().putInt("CustomPotionColor", BrewUtils.getColor(mobEffectInstance, brewEffectInstance));
                    this.setItemSlot(EquipmentSlot.MAINHAND, brew);
                    this.usingTime = this.overwhelmed > 0 ? this.getMainHandItem().getUseDuration() / 2 : this.getMainHandItem().getUseDuration();
                    this.setUsingItem(true);
                    if (!this.isSilent()) {
                        this.level.playSound((Player)null, this.getX(), this.getY(), this.getZ(), SoundEvents.WITCH_DRINK, this.getSoundSource(), 1.0F, 0.8F + this.random.nextFloat() * 0.4F);
                    }

                    AttributeInstance attributeinstance = this.getAttribute(Attributes.MOVEMENT_SPEED);
                    attributeinstance.removeModifier(SPEED_MODIFIER_DRINKING);
                    attributeinstance.addTransientModifier(SPEED_MODIFIER_DRINKING);
                } else if (this.getMainHandItem().getItem() instanceof BrewItem){
                    this.usingTime = this.overwhelmed > 0 ? this.getMainHandItem().getUseDuration() / 2 : this.getMainHandItem().getUseDuration();
                    this.setUsingItem(true);
                    AttributeInstance attributeinstance = this.getAttribute(Attributes.MOVEMENT_SPEED);
                    attributeinstance.removeModifier(SPEED_MODIFIER_DRINKING);
                    attributeinstance.addTransientModifier(SPEED_MODIFIER_DRINKING);
                }
            }

            if (this.random.nextFloat() < 7.5E-4F) {
                this.level.broadcastEntityEvent(this, (byte)15);
            }
        }

        super.aiStep();
    }

@SubscribeEvent
    public static void playerOnTick(PlayerTickEvent.Pre e) {
        Player player = e.getEntity();
        if (!(player instanceof ServerPlayer serverPlayer) || player.getCommandSenderWorld().getGameTime() % ServerConfig.REGEN_INTERVAL.get() != 0)
            return;

        ManaCap mana = CapabilityRegistry.getMana(player);
        if (mana == null)
            return;
        boolean sync = false;
        // Force sync mana to client because client caps vanish on world change
        boolean forceSync = player.level().getGameTime() % 60 == 0;
        if (mana.getCurrentMana() != mana.getMaxMana() || forceSync) {
            double regenPerSecond = ManaUtil.getManaRegen(player) / Math.max(1, ((int) MEAN_TPS / ServerConfig.REGEN_INTERVAL.get()));
            mana.addMana(regenPerSecond);
            sync = true;
        }
        ManaUtil.Mana maxmana = ManaUtil.calcMaxMana(player);
        int max = maxmana.getRealMax();
        if (mana.getMaxMana() != max || forceSync) {
            mana.setMaxMana(max);
            mana.setReserve(maxmana.Reserve());
            sync = true;
        }

        if (sync) {
            mana.syncToClient(serverPlayer);
        }
    }

@Override
    public double setMana(double mana) {
        if (mana > getMaxMana()) {
            this.manaData.setMana(getMaxMana());
        } else if (mana < 0) {
            this.manaData.setMana(0);
        } else {
            this.manaData.setMana(mana);
        }
        entity.setData(AttachmentsRegistry.MANA_ATTACHMENT, manaData);
        return this.getCurrentMana();
    }

